// Symbol catalogue UI. Source assets and attribution are compiled into the offline preview.
Object.assign(suite,{symbolMode:'guide',symbolCategory:'all',symbolQuery:'',symbolKind:'all',symbolPalette:'day',symbolPage:0,symbolId:'',symbolGuide:'',buoyRegion:'A'});
const symbolById=new Map(chartSymbolLibrary.items.map(s=>[s.id,s]));
const symbolCategoryName=id=>chartSymbolLibrary.categories.find(c=>c.id===id)?.name||'Chart objects';
const symbolNumber=n=>n.toLocaleString('en-GB');
const symbolTitle=s=>s.description? s.description[0].toUpperCase()+s.description.slice(1):'Unnamed source variant';
const symbolPageSize=36;
let buoyDrawingId=0;
function guideVariant(g){const r=suite.buoyRegion;return {...g,code:g['code'+r]||g.code,colors:g['colors'+r]||g.colors,day:g['day'+r]||g.day,light:g['light'+r]||g.light};}
function buoyDrawing(g){
 const colors={red:'#df5c5f',green:'#369567',yellow:'#f0ca54',black:'#202d31',white:'#f6f4de',blue:'#397cc2'},c=g.colors.map(k=>colors[k]);
 const id='buoy-body-'+(++buoyDrawingId),shape=g.shape==='can'?'M32 67H68V115H32Z':g.shape==='cone'?'M50 61L73 115H27Z':'M44 58H56L64 113H36Z';
 const cone=(y,up)=>`<path d="${up?'M50 '+y+'L40 '+(y+15)+'H60Z':'M40 '+y+'H60L50 '+(y+15)+'Z'}"/>`;
 let top='';const paint=g.top==='sphere'?colors.red:['x','cross'].includes(g.top)?colors.yellow:['can','cone'].includes(g.top)?c[0]:colors.black;
 if(g.top==='can')top='<rect x="42" y="26" width="16" height="21"/>';
 else if(g.top==='cone')top=cone(25,true);
 else if(g.top==='north')top=cone(11,true)+cone(31,true);
 else if(g.top==='south')top=cone(11,false)+cone(31,false);
 else if(g.top==='east')top=cone(11,true)+cone(31,false);
 else if(g.top==='west')top=cone(11,false)+cone(31,true);
 else if(g.top==='spheres')top='<circle cx="50" cy="18" r="8"/><circle cx="50" cy="39" r="8"/>';
 else if(g.top==='sphere')top='<circle cx="50" cy="30" r="10"/>';
 else if(g.top==='x')top='<path d="M40 21L60 43M60 21L40 43" fill="none" stroke-width="7"/>';
 else top='<path d="M50 15V47M36 29H64" fill="none" stroke-width="7"/>';
 return `<svg class="buoy-drawing" viewBox="0 0 100 140" aria-hidden="true"><ellipse cx="50" cy="119" rx="34" ry="5" fill="#233c3620"/><path d="M50 44V69" stroke="#66736a" stroke-width="2"/><defs><clipPath id="${id}"><path d="${shape}"/></clipPath></defs><g clip-path="url(#${id})">${c.map((p,i)=>g.vertical?`<rect x="${25+i*50/c.length}" y="55" width="${50/c.length+.2}" height="65" fill="${p}"/>`:`<rect x="25" y="${55+i*65/c.length}" width="50" height="${65/c.length+.2}" fill="${p}"/>`).join('')}</g><path d="${shape}" fill="none" stroke="#26393380" stroke-width="1.3"/><g fill="${paint}" stroke="${paint}" stroke-linejoin="round">${top}</g><path d="M18 118Q26 114 34 118T50 118T66 118T82 118" fill="none" stroke="#729e9b" stroke-width="1.2"/></svg>`;
}
function symbolGlyph(s,palette='day',size=64){
 if(!s)return '';
 if(s.bitmap){const b=s.bitmap,k=Math.min(size/b.width,size/b.height,3),w=b.width*k,h=b.height*k;return `<span class="symbol-glyph" aria-hidden="true" style="width:${w}px;height:${h}px;background-image:var(--symbol-sheet-${palette});background-size:${chartSymbolLibrary.sheet.width*k}px ${chartSymbolLibrary.sheet.height*k}px;background-position:-${b.x*k}px -${b.y*k}px"></span>`;}
 const v=s.vector,p=chartSymbolLibrary.palettes[palette];
 return `<svg class="symbol-vector" aria-hidden="true" viewBox="${v.viewBox.join(' ')}" width="${size}" height="${size}">${v.shapes.map(sh=>{const col=p[sh.color]||p.CHBLK,stroke=Math.max(sh.width*3,Math.max(v.viewBox[2],v.viewBox[3])*.008);return sh.type==='circle'?`<circle cx="${sh.cx}" cy="${sh.cy}" r="${sh.r}" fill="${sh.fill?col:'none'}" stroke="${col}" stroke-width="${stroke}"/>`:`<path d="${sh.d}" stroke="${col}" stroke-width="${stroke}" fill="${sh.fill?col:'none'}" stroke-linejoin="round" stroke-linecap="round"/>`;}).join('')}</svg>`;
}
function symbolTile(s,palette,size=64){return `<span class="symbol-sample sample-${palette}">${symbolGlyph(s,palette,size)}</span>`;}
function atlasHeading(){return `<header class="atlas-heading"><div><span class="eyebrow mint">CHART REFERENCE / SJÖKORTSTECKEN</span><h1>Symbol atlas<span class="atlas-edition">01—${symbolNumber(chartSymbolLibrary.items.length)}</span></h1></div><div class="atlas-heading-actions"><button class="atlas-source" data-action="symbolSources" aria-label="Sources & coverage">${icon('info')}<span>Sources & coverage</span></button><button class="view-back" data-action="back" data-context-return></button></div></header>`;}
function atlasTabs(){return `<div class="atlas-tabs" role="group" aria-label="Reference section">${[['guide','Seamark guide'],['library','Complete library']].map(([id,label])=>`<button data-symbol-mode="${id}" aria-pressed="${suite.symbolMode===id}" class="${suite.symbolMode===id?'selected':''}">${label}${id==='library'?'<span>'+symbolNumber(chartSymbolLibrary.items.length)+'</span>':''}</button>`).join('')}<span class="atlas-offline"><i class="status-dot"></i> Available offline</span></div>`;}
function atlasGuide(){
 const groups=[['Lateral','01','Follow the fairway.','Port and starboard are read in the conventional direction of buoyage.'],['Cardinal','02','Find the safe side.','The name tells you which side of the mark to pass.'],['Other marks','03','Read the situation.','Recognise isolated dangers, safe water and special-purpose marks.']];
 return `<section class="atlas-intro"><div><span class="eyebrow">A LANGUAGE OF SHAPE, COLOUR & LIGHT</span><h2>Know what you’re looking at.</h2><p>Physical marks alongside their chart symbols.<br>Choose an example to explore its meaning and appearance.</p></div><div class="buoy-region"><span>Buoyage region</span><div class="segment" role="group" aria-label="Buoyage region"><button data-buoy-region="A" aria-pressed="${suite.buoyRegion==='A'}" class="${suite.buoyRegion==='A'?'selected':''}">A <small>Sweden</small></button><button data-buoy-region="B" aria-pressed="${suite.buoyRegion==='B'}" class="${suite.buoyRegion==='B'?'selected':''}">B</button></div><small>${suite.buoyRegion==='A'?'Red to port · green to starboard':'Green to port · red to starboard'}</small></div></section>${groups.map(([family,n,title,copy])=>`<section class="seamark-section"><div class="seamark-section-heading"><span>${n}</span><div><h3>${title}</h3><p>${copy}</p></div><small>${family.toUpperCase()}</small></div><div class="seamark-grid">${seamarkGuide.filter(g=>g.family===family).map(raw=>{const g=guideVariant(raw);return `<button class="seamark-card" data-symbol-guide="${g.id}"><span class="seamark-art">${buoyDrawing(g)}<span class="seamark-chart-preview">${g.code?symbolGlyph(symbolById.get('point:'+g.code),'day',38):'<span class="physical-only">Physical<br>example</span>'}<small>${g.code?'ON CHART':'ILLUSTRATION'}</small></span></span><span class="seamark-card-copy"><b>${g.en}</b><span>${g.sv}</span><small>${g.meaning}</small></span><span class="seamark-open">Explore ${icon('chevron')}</span></button>`;}).join('')}</div></section>`).join('')}<section class="atlas-more"><div><span class="eyebrow mint">BEYOND THE BUOYS</span><h2>The rest of the chart.</h2><p>Lights, hazards, depths, routes, harbours, inland signs and more.</p></div><button class="btn primary" data-symbol-mode="library">Browse all ${symbolNumber(chartSymbolLibrary.items.length)} ${icon('chevron')}</button></section><p class="atlas-footnote">Buoy shapes are illustrative. Chart glyphs: OpenCPN. Guide: IALA and Sjöfartsverket. ${suite.buoyRegion==='A'?'Region A includes Sweden.':'Region B includes the Americas, Japan, Korea and the Philippines.'} Always read the charted direction of buoyage.</p>`;
}
function filteredSymbols(){
 const normal=s=>s.toLocaleLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
 const tokens=normal(suite.symbolQuery).split(/\s+/).filter(Boolean);
 return chartSymbolLibrary.items.filter(s=>{
  if(suite.symbolCategory!=='all'&&s.category!==suite.symbolCategory)return false;
  if(suite.symbolKind!=='all'&&s.kind!==suite.symbolKind)return false;
  const cat=chartSymbolLibrary.categories.find(c=>c.id===s.category),guides=seamarkGuide.filter(g=>[g.code,g.codeA,g.codeB].includes(s.code));
  const text=normal([s.code,s.description,cat.name,cat.sv,...guides.flatMap(g=>[g.en,g.sv,g.meaning])].join(' '));
  return tokens.every(t=>text.includes(t));
 });
}
function symbolResults(){
 const all=filteredSymbols(),pages=Math.max(1,Math.ceil(all.length/symbolPageSize));suite.symbolPage=Math.max(0,Math.min(suite.symbolPage,pages-1));
 const start=suite.symbolPage*symbolPageSize,items=all.slice(start,start+symbolPageSize);
 return `<div class="symbol-result-heading"><span role="status" aria-live="polite">${symbolNumber(all.length)} ${all.length===1?'example':'examples'}<small>${all.length?' · '+(start+1)+'–'+Math.min(start+symbolPageSize,all.length):''}</small></span><label>Page <select id="symbolPageSelect" aria-label="Symbol results page">${Array.from({length:pages},(_,i)=>`<option value="${i}" ${i===suite.symbolPage?'selected':''}>${i+1} / ${pages}</option>`).join('')}</select></label></div>${items.length?`<div class="symbol-grid">${items.map(s=>`<button class="symbol-card" data-symbol-id="${s.id}" title="${esc(symbolTitle(s))}">${symbolTile(s,suite.symbolPalette)}<span class="symbol-card-copy"><b>${s.code}</b><span>${esc(symbolTitle(s))}</span><small>${s.kind==='point'?'POINT':s.kind==='line'?'LINE SEGMENT':'PATTERN TILE'}</small></span></button>`).join('')}</div><div class="symbol-pagination"><button class="btn" data-symbol-page="${suite.symbolPage-1}" ${suite.symbolPage===0?'disabled':''}>${icon('arrow')} Previous</button><span>${suite.symbolPage+1} / ${pages}</span><button class="btn" data-symbol-page="${suite.symbolPage+1}" ${suite.symbolPage===pages-1?'disabled':''}>Next ${icon('chevron')}</button></div>`:`<div class="empty-state symbol-empty">${icon('search')}<h3>No matching symbols.</h3><p>Try an English name, a Swedish category or a code such as BOYCAR01.</p><button class="btn" data-action="resetSymbols">Clear search & filters</button></div>`}`;
}
function atlasLibrary(){return `<div class="atlas-library"><aside class="symbol-categories" aria-label="Symbol categories"><span class="eyebrow">EXPLORE BY CATEGORY</span>${[{id:'all',name:'All symbols'},...chartSymbolLibrary.categories].map(c=>`<button data-symbol-category="${c.id}" aria-pressed="${suite.symbolCategory===c.id}" class="${suite.symbolCategory===c.id?'selected':''}"><span>${c.name}</span><small>${symbolNumber(c.id==='all'?chartSymbolLibrary.items.length:chartSymbolLibrary.items.filter(s=>s.category===c.id).length)}</small></button>`).join('')}<button class="symbol-export" data-action="exportSymbols">${icon('download')} Export catalogue</button></aside><section class="symbol-browser" aria-label="Chart symbol library"><div class="symbol-controls"><label class="symbol-search">${icon('search')}<input id="symbolSearch" aria-label="Search chart symbols" placeholder="Search symbol, meaning or code…" value="${esc(suite.symbolQuery)}" autocomplete="off" spellcheck="false"><button class="symbol-clear" data-action="clearSymbolSearch" aria-label="Clear symbol search" ${suite.symbolQuery?'':'hidden'}>${icon('close')}</button></label><div class="symbol-filters"><label class="symbol-kind">Show <select id="symbolKind" aria-label="Symbol geometry"><option value="all" ${suite.symbolKind==='all'?'selected':''}>All types</option><option value="point" ${suite.symbolKind==='point'?'selected':''}>Point symbols</option><option value="line" ${suite.symbolKind==='line'?'selected':''}>Line styles</option><option value="pattern" ${suite.symbolKind==='pattern'?'selected':''}>Area patterns</option></select></label><div class="symbol-palettes" role="group" aria-label="Symbol palette">${['day','dusk','night'].map(p=>`<button data-symbol-palette="${p}" aria-pressed="${suite.symbolPalette===p}" class="${suite.symbolPalette===p?'selected':''}">${p[0].toUpperCase()+p.slice(1)}</button>`).join('')}</div></div></div><div id="symbolResults">${symbolResults()}</div><p class="atlas-footnote">All unique definitions in the pinned OpenCPN library. Examples include paper-chart, simplified and inland variants. Source descriptions are retained; some variants are unnamed. Area patterns and lines show individual repeat elements.</p></section></div>`;}
function renderSymbolAtlas(){return `<div class="symbol-atlas">${atlasHeading()}${atlasTabs()}${suite.symbolMode==='guide'?atlasGuide():atlasLibrary()}</div>`;}
function symbolDetailBody(){
 const g0=seamarkGuide.find(g=>g.id===suite.symbolGuide),g=g0?guideVariant(g0):null,s=g?.code?symbolById.get('point:'+g.code):symbolById.get(suite.symbolId);
 if(g&&!s)return `<div class="seamark-detail-illustration">${buoyDrawing(g)}<span>PHYSICAL MARK · ILLUSTRATION</span></div><p class="symbol-sw-name">${g.sv}</p><p class="symbol-meaning">${g.meaning}</p>${row('Daymark',g.day)}${row('Light',g.light)}${note(g.note)}${symbolDetailSources(true)}`;
 if(!s)return '<p class="muted-copy">No symbol selected.</p>';
 return `${g?`<p class="symbol-sw-name">${g.sv} · IALA ${g.family==='Lateral'?'region '+suite.buoyRegion:'A & B'}</p><p class="symbol-meaning">${g.meaning}</p>`:`<p class="symbol-meaning">${esc(symbolTitle(s))}</p>`}<div class="symbol-detail-palettes">${['day','dusk','night'].map(p=>`<figure>${symbolTile(s,p,88)}<figcaption>${p[0].toUpperCase()+p.slice(1)}</figcaption></figure>`).join('')}</div>${g?`${row('Daymark',g.day)}${row('Light',g.light)}`:''}${row('Symbol code','<code>'+s.code+'</code>')}${row('Category',symbolCategoryName(s.category))}${row('Geometry',s.kind==='point'?'Point symbol':s.kind==='line'?'Repeating line segment':'Area-pattern tile')}${row('Rendering',s.bitmap?'Source bitmap · '+s.bitmap.width+' × '+s.bitmap.height+' px':'Vector geometry · source HPGL')}${s.bitmap?row('Source anchor',s.bitmap.pivot.x+', '+s.bitmap.pivot.y+' px'):''}<p class="note">${s.kind==='point'?'The chart renderer combines symbols with object attributes, labels, lights and topmarks.':'This is one repeat element. Placement, spacing, rotation and clipping belong to the chart renderer.'}</p>${!chartMarkerDesigned(s)?'<p class="note">This definition is placed as a labelled reference pin. Its exact source glyph is shown above.</p>':''}${button('Place on demo chart','placeAtlasSymbol','primary full')}<details class="sensor-details"><summary>Implementation reference</summary><div class="symbol-code-block"><code>${esc(JSON.stringify({id:s.id,category:s.category,...(s.bitmap?{sprite:s.bitmap}:{vector:s.vector}),sourceCommit:chartSymbolLibrary.source.commit},null,2))}</code></div><button class="btn full" data-action="exportSymbol">${icon('download')} Export this definition</button></details>${symbolDetailSources(!!g)}`;
}
function symbolDetailSources(guide=false){return `<div class="symbol-attribution">${guide?'Meaning: IALA / Sjöfartsverket. ':''}Glyphs: OpenCPN · GPL-2.0.<button data-action="symbolSources">Sources & coverage ${icon('chevron')}</button></div>`;}
function symbolSources(){openModal('About this atlas',`<p>A complete index of <b>${symbolNumber(chartSymbolLibrary.items.length)} unique definitions</b> in one pinned OpenCPN symbol library: 1,018 point symbols, 59 line styles and 30 area patterns.</p><p>The seamark guide adds Swedish names, IALA region A/B examples and a physical emergency-wreck buoy illustration. The library also contains display aids and inland signs.</p><p>This is a portrayal reference. It does not include every national variant or implement the conditional rules, scale selection and object attributes needed by a production chart renderer.</p><div class="symbol-source-links"><a href="https://github.com/OpenCPN/OpenCPN/tree/${chartSymbolLibrary.source.commit}/data/s57data" target="_blank" rel="noopener noreferrer">OpenCPN · pinned source library ↗</a><a href="https://sjofartsverket.se/sv/tjanster/transporter-och-farleder2/farleder-och-underhall/sjomarken/flytande-sjomarken/" target="_blank" rel="noopener noreferrer">Sjöfartsverket · Swedish seamarks ↗</a><a href="https://academy.iala.int/product/r1001/" target="_blank" rel="noopener noreferrer">IALA · Maritime Buoyage System ↗</a><a href="https://www.sjofartsverket.se/sv/tjanster/sjokortsprodukter/publikationer/" target="_blank" rel="noopener noreferrer">Kort 1 · Swedish chart reference ↗</a><a href="https://iho.int/en/standards-and-specifications" target="_blank" rel="noopener noreferrer">IHO · chart portrayal standards ↗</a></div><details class="sensor-details"><summary>OpenCPN resource license · GPL-2.0</summary><pre class="symbol-code-block">${esc(chartSymbolLicense)}</pre></details><p class="note">OpenCPN resources are distributed under GPL-2.0; the original source, license and provenance are included in the design package. Source snapshot: ${chartSymbolLibrary.source.commit.slice(0,12)} · retrieved 28 Sep 2026. Guide illustrations are original. See SYMBOLS.md for the production handoff.</p>`,'SOURCE & SCOPE');}
function refreshSymbolAtlas(selector){const scroll=$('#fullView').scrollTop;renderView();$('#fullView').scrollTop=scroll;if(selector)$('#fullView').querySelector(selector)?.focus({preventScroll:true});}
function handleSymbolClick(b){
 if(b.dataset.symbolId){suite.symbolId=b.dataset.symbolId;suite.symbolGuide='';openPanel('symbolDetail');return true;}
 if(b.dataset.symbolGuide){suite.symbolGuide=b.dataset.symbolGuide;suite.symbolId='';openPanel('symbolDetail');return true;}
 if(b.dataset.symbolMode){suite.symbolMode=b.dataset.symbolMode;renderView();$('#fullView').scrollTop=0;$('#fullView').querySelector(`[data-symbol-mode="${suite.symbolMode}"]`)?.focus({preventScroll:true});return true;}
 if(b.dataset.buoyRegion){suite.buoyRegion=b.dataset.buoyRegion;refreshSymbolAtlas(`[data-buoy-region="${suite.buoyRegion}"]`);return true;}
 if(b.dataset.symbolCategory){suite.symbolCategory=b.dataset.symbolCategory;suite.symbolPage=0;refreshSymbolAtlas(`[data-symbol-category="${suite.symbolCategory}"]`);return true;}
 if(b.dataset.symbolPalette){suite.symbolPalette=b.dataset.symbolPalette;refreshSymbolAtlas(`[data-symbol-palette="${suite.symbolPalette}"]`);return true;}
 if(b.dataset.symbolPage!==undefined){suite.symbolPage=+b.dataset.symbolPage;$('#symbolResults').innerHTML=symbolResults();$('#symbolResults').scrollIntoView({block:'start'});$('#symbolPageSelect').focus({preventScroll:true});return true;}
 return false;
}
Object.assign(actions,{
 showSymbols:()=>fullView('symbols'),symbolSources,
 clearSymbolSearch:()=>{suite.symbolQuery='';suite.symbolPage=0;$('#symbolSearch').value='';$('.symbol-clear').hidden=true;$('#symbolResults').innerHTML=symbolResults();$('#symbolSearch').focus({preventScroll:true});},
 resetSymbols:()=>{suite.symbolQuery='';suite.symbolCategory='all';suite.symbolKind='all';suite.symbolPage=0;refreshSymbolAtlas('#symbolSearch');},
 exportSymbols:()=>{download('OpenNavX-symbol-catalogue.json',{...chartSymbolLibrary,seamarkGuide,referenceOnly:true,notice:'OpenCPN resources GPL-2.0. Source assets and license are included in the design package.'});toast('Catalogue download requested');},
 exportSymbol:()=>{const g=seamarkGuide.find(g=>g.id===suite.symbolGuide),s=g?symbolById.get('point:'+guideVariant(g).code):symbolById.get(suite.symbolId);if(s){download('OpenNavX-'+s.code+'.json',{symbol:s,guide:g||null,source:chartSymbolLibrary.source,palettes:chartSymbolLibrary.palettes,referenceOnly:true});toast(s.code+' download requested');}}
});
document.addEventListener('input',e=>{if(e.target.id==='symbolSearch'){suite.symbolQuery=e.target.value;$('.symbol-clear').hidden=!suite.symbolQuery;suite.symbolPage=0;$('#symbolResults').innerHTML=symbolResults();}});
document.addEventListener('change',e=>{if(e.target.id==='symbolKind'){suite.symbolKind=e.target.value;suite.symbolPage=0;$('#symbolResults').innerHTML=symbolResults();}if(e.target.id==='symbolPageSelect'){suite.symbolPage=+e.target.value;$('#symbolResults').innerHTML=symbolResults();$('#symbolPageSelect').focus({preventScroll:true});}});
